use anyhow::{Context,Result};use guidance_protocol::{Request,Response,VERSION};use guidance_runtime::Runtime;use serde_json::{json,Value};use tokio::io::{AsyncBufReadExt,AsyncWriteExt,BufReader};
async fn run(rt:&Runtime,q:Request)->Response{let id=q.id.clone();if q.protocol!=VERSION{return Response::err(id,"unsupported_protocol","expected 1.0".into())}let r:Result<Value>=async{Ok(match q.method.as_str(){"runtime.status"=>json!({"version":env!("CARGO_PKG_VERSION"),"state":"Running","workloads":rt.list()}),"workload.list"=>json!(rt.list()),"workload.start"=>{rt.start(pid(&q.params)?).await?;json!({"accepted":true})},"workload.stop"=>{rt.stop(pid(&q.params)?).await?;json!({"accepted":true})},"workload.restart"=>{rt.restart(pid(&q.params)?).await?;json!({"accepted":true})},"workload.stop_all"=>{rt.stop_all().await;json!({"accepted":true})},"workload.start_all"=>{rt.start_enabled().await;json!({"accepted":true})},"workload.logs"=>json!({"lines":rt.logs(pid(&q.params)?,q.params.get("tail").and_then(Value::as_u64).unwrap_or(100)as usize).await?}),"diagnostics.summary"=>json!({"workloads":rt.list()}),_=>anyhow::bail!("method not found")})}.await;match r{Ok(x)=>Response::ok(id,x),Err(e)=>Response::err(id,if e.to_string().contains("not found"){"not_found"}else{"internal_error"},e.to_string())}}
fn pid(v:&Value)->Result<&str>{v.get("workload_id").and_then(Value::as_str).context("workload_id required")}
async fn stream<S:tokio::io::AsyncRead+tokio::io::AsyncWrite+Unpin>(s:S,rt:Runtime)->Result<()>{let(r,mut w)=tokio::io::split(s);let mut l=BufReader::new(r).lines();while let Some(x)=l.next_line().await?{if x.len()>1_048_576{break}let z=match serde_json::from_str(&x){Ok(q)=>run(&rt,q).await,Err(e)=>Response::err("unknown".into(),"invalid_request",e.to_string())};w.write_all(serde_json::to_string(&z)?.as_bytes()).await?;w.write_all(b"\n").await?;}Ok(())}
#[cfg(unix)]pub async fn serve(rt:Runtime)->Result<()>{let _=tokio::fs::remove_file(guidance_protocol::SOCKET).await;let l=tokio::net::UnixListener::bind(guidance_protocol::SOCKET)?;loop{let(s,_)=l.accept().await?;let r=rt.clone();tokio::spawn(async move{let _=stream(s,r).await;});}}
#[cfg(windows)]pub async fn serve(rt:Runtime)->Result<()>{use tokio::net::windows::named_pipe::ServerOptions;loop{let s=ServerOptions::new().first_pipe_instance(false).create(guidance_protocol::PIPE)?;s.connect().await?;let r=rt.clone();tokio::spawn(async move{let _=stream(s,r).await;});}}
pub async fn request(q:Request)->Result<Response>{#[cfg(unix)]let s=tokio::net::UnixStream::connect(guidance_protocol::SOCKET).await?;#[cfg(windows)]let s=tokio::net::windows::named_pipe::ClientOptions::new().open(guidance_protocol::PIPE)?;let(r,mut w)=tokio::io::split(s);w.write_all(serde_json::to_string(&q)?.as_bytes()).await?;w.write_all(b"\n").await?;let mut x=String::new();BufReader::new(r).read_line(&mut x).await?;Ok(serde_json::from_str(&x)?)}
